for (const a of apples) {
  total = total + a;
}
console.log(total);

const onesA = 7, tensA = 2;
const onesB = 5, tensB = 1;
const onesSum = onesA + onesB;        // 12
const onesDigit = onesSum % 10;       // 2 stays
const carry = Math.floor(onesSum / 10); // 1 ten carried
const tensDigit = tensA + tensB + carry; // 4
console.log(tensDigit * 10 + onesDigit);
